import {OpenWorldSimulation} from '/workspace/scratch/e34866a435ab/Experiment-3/src/simulation/open-world/session.ts';
import {trackPoint, surfaceSample} from '/workspace/scratch/e34866a435ab/Experiment-3/src/simulation/track.ts';
import {RoutePath} from '/workspace/scratch/e34866a435ab/Experiment-3/src/simulation/open-world/route-path.ts';
import {RouteDriver} from '/workspace/scratch/e34866a435ab/Experiment-3/src/simulation/open-world/route-driver.ts';
import {controls} from '/workspace/scratch/e34866a435ab/Experiment-3/src/simulation/config.ts';
for (const speed of [24,32]) {
const sim=new OpenWorldSimulation({vehicle:'tc1',tileBudget:12});
const edge=sim.world.network.edges.find(e=>e.id==='quarry#0');
const p=sim.world.network.at(edge.offset+1940,trackPoint());
sim.placeAt(sim.player,p.x,p.z,Math.atan2(p.tx,p.tz),p.y+.5);
for(let i=0;i<120;i++)sim.step(1/120);
const car=sim.player;
const path=new RoutePath(sim.world.network,[{edge:edge.index,dir:1,from:1900,to:2200}],false);
const driver=new RouteDriver(car,path,1);driver.relocate(40);
car.body.velocity.set(p.tx*speed,p.gradient*speed,p.tz*speed);car.gear=4;
for(const tire of car.tires)tire.omega=speed/tire.radius;
sim.setInput({...controls(),throttle:.3});
let air=0,longestAir=0,minUp=1,maxImpact=0,offRoad=0,peakClearance=0,label='';
const changes=[],flights=[],surface=surfaceSample();
let flightStart=null;
for(let i=0;i<420;i++) {
 driver.update(1/120,[car]);sim.setInput({...car.input,throttle:.3,brake:0});sim.step(1/120);
 const pos=car.body.position, grounded=car.tires.some(t=>t.load>20);
 if (!grounded) {if(air===0)flightStart={i,x:pos.x,y:pos.y,z:pos.z,speed:car.speed,vy:car.body.velocity.y};air+=1/120;}
 else if(air>0) {flights.push({seconds:air,takeoff:flightStart,landing:{i,x:pos.x,y:pos.y,z:pos.z,vy:car.body.velocity.y,up:car.up.y}});air=0;}
 longestAir=Math.max(longestAir,air);minUp=Math.min(minUp,car.up.y);maxImpact=Math.max(maxImpact,car.impact);offRoad+=Number(!sim.track.query.onRoad);
 sim.track.sample(pos.x,pos.z,surface,pos.y);peakClearance=Math.max(peakClearance,pos.y-surface.height);
 const s=sim.skills.status();if(s.label!==label){changes.push({i,s,up:car.up.y,normalVelocity:car.body.velocity.dot(surface.normal),loads:car.tires.map(t=>t.load)});label=s.label;}
}
console.log(JSON.stringify({initialSpeed:speed,flights,longestAir,minUp,maxImpact,offRoad,peakClearance,changes,final:sim.skills.status()}));
}
